let apps = workspace.runningApplications

for app in apps {
    if let appName = app.localizedName, appName.contains("Simulator") {
        app.activateWithOptions([])
        Thread.sleep(forTimeInterval: 0.5)

        // Try to find the simulator window and post an event to it
        for window in NSApplication.shared.windows {
            print("Found window: \(window.title)")
        }

        // Create and post NSEvent directly
        let point = CGPoint(x: 544, y: 330)

        let mouseDown = NSEvent.mouseEvent(
            with: .leftMouseDown,
            at: point,
            modifierFlags: [],
            timestamp: Date().timeIntervalSince1970,
            windowNumber: 0,
            context: nil
        )!

        let mouseUp = NSEvent.mouseEvent(
            with: .leftMouseUp,
            at: point,
            modifierFlags: [],
            timestamp: Date().timeIntervalSince1970,
            windowNumber: 0,
            context: nil
        )!

        NSApplication.shared.sendEvent(mouseDown)
        Thread.sleep(forTimeInterval: 0.1)
        NSApplication.shared.sendEvent(mouseUp)

        print("Sent NSEvent mouse click")
        break
    }
}
